<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';
use InaudisVote\Core\Csrf;use InaudisVote\Services\ElectionService;use InaudisVote\Services\VotingService;
$token=(string)($_GET['token']??$_POST['token']??'');$context=$token!==''?VotingService::resolveToken($token):null;$error=null;$receipt=null;$questions=[];
if($_SERVER['REQUEST_METHOD']==='POST'&&Csrf::validate($_POST['_csrf']??null)){try{$action=(string)($_POST['action']??'vote');if($action==='verify_otp'){if(!VotingService::verifyOtp($token,(string)($_POST['otp']??'')))throw new RuntimeException('OTP inválido o vencido.');$context=VotingService::resolveToken($token);}else{$receipt=VotingService::submit($token,(array)($_POST['answers']??[]));$context=VotingService::resolveToken($token);}}catch(Throwable $e){$error=$e->getMessage();}}elseif($_SERVER['REQUEST_METHOD']==='POST'){$error='Solicitud inválida. Recarga la página.';}if($context){$questions=ElectionService::questions((int)$context['election_id']);}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Votar | INAUDIS Vota</title><link rel="stylesheet" href="/assets/inaudis-vota.css"></head><body class="vota-ui"><main class="v-voter"><header class="v-voter-head"><div class="v-brand" style="margin:0;color:var(--navy)"><span class="v-brandmark" style="background:linear-gradient(135deg,var(--navy) 0 45%,var(--orange) 46% 57%,var(--navy) 58%)"></span><span>INAUDIS<small style="opacity:.65">VOTA</small></span></div><span class="v-status v-status-open">🔒 Sesión segura</span></header><section class="v-voter-card"><?php if($error):?><div class="v-alert v-alert-error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(!$context):?><div class="v-kicker">Acceso</div><h1 class="v-title">Enlace no válido</h1><p class="v-muted">La invitación no existe o ya no está disponible.</p><?php elseif($receipt):?><div class="v-receipt"><div class="v-checkmark">✓</div><div class="v-kicker" style="color:var(--teal)">Proceso completado</div><h1 class="v-title">¡Tu voto fue registrado correctamente!</h1><p class="v-muted">Gracias por participar. Conserva este comprobante como respaldo.</p><div class="v-card v-pad" style="text-align:left;margin-top:24px"><strong>Comprobante de voto</strong><p class="v-muted" style="font-size:12px">Huella criptográfica SHA-256</p><div class="v-hash"><?=htmlspecialchars($receipt)?></div></div><div class="v-security" style="justify-content:center"><span>🔒 Voto seguro</span><span>✓ Identidad separada</span><span>✓ Verificable</span></div></div><?php elseif(empty($context['verified_at'])&&!$context['consumed_at']):?><div class="v-kicker">Paso 1 de 2 · Identidad</div><h1 class="v-title">Verifica tu identidad</h1><div class="v-accent-line"></div><p class="v-muted">Ingresa el código de 6 dígitos asociado a tu invitación para acceder a la papeleta.</p><form method="post" style="margin-top:26px"><?=Csrf::input()?><input type="hidden" name="action" value="verify_otp"><input type="hidden" name="token" value="<?=htmlspecialchars($token,ENT_QUOTES)?>"><label class="v-label">Código de verificación</label><input class="v-field" style="font-size:25px;text-align:center;letter-spacing:.45em" name="otp" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" required placeholder="000000"><button class="v-btn v-btn-orange" style="width:100%;margin-top:18px" type="submit">Validar y continuar →</button></form><div class="v-security"><span>🔒 Conexión segura</span><span>◷ Código temporal</span></div><?php elseif(!VotingService::canVote($context)):?><div class="v-alert v-alert-warn">Esta invitación no está habilitada. El proceso puede estar cerrado, fuera de horario o el voto ya fue emitido.</div><?php else:?><div class="v-kicker">Paso 2 de 2 · Papeleta</div><h1 class="v-title"><?=htmlspecialchars((string)$context['election_title'])?></h1><div class="v-accent-line"></div><p class="v-muted">Selecciona tu preferencia. Tu identidad y tu papeleta se procesan por separado.</p><form method="post" style="margin-top:24px"><?=Csrf::input()?><input type="hidden" name="action" value="vote"><input type="hidden" name="token" value="<?=htmlspecialchars($token,ENT_QUOTES)?>"><?php foreach($questions as $q):?><section style="margin-bottom:28px"><h2 style="font-size:18px"><?=htmlspecialchars($q['text'])?></h2><?php foreach($q['options'] as $o):?><label class="v-option"><input type="<?=$q['question_type']==='multiple'?'checkbox':'radio'?>" name="answers[<?=$q['id']?>][]" value="<?=$o['id']?>"><span><strong><?=htmlspecialchars($o['label'])?></strong></span></label><?php endforeach;?><?php if($q['question_type']==='multiple'):?><p class="v-muted" style="font-size:12px">Selecciona entre <?=$q['min_choices']?> y <?=$q['max_choices']?> alternativas.</p><?php endif;?></section><?php endforeach;?><div class="v-orange-note" style="margin-bottom:16px"><strong>Revisa antes de confirmar.</strong> Una vez emitido, el voto no podrá modificarse.</div><button class="v-btn v-btn-orange" style="width:100%;font-size:16px" onclick="return confirm('¿Confirmas tu voto? Esta acción no podrá modificarse.');">Confirmar voto →</button></form><?php endif;?></section></main></body></html>